<?php require_once __DIR__.'/../config/bootstrap.php';if(user())redirect('/gamestore/index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){$error='Preencha os campos corretamente. A senha deve ter ao menos 8 caracteres.';}else{$s=db()->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');try{$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer'];redirect('/gamestore/index.php');}catch(PDOException $e){$error='Este e-mail já está cadastrado.';}}}$pageTitle='Criar cadastro';require __DIR__.'/../includes/header.php';?><div class="form-card"><h1 class="h3 fw-bold">Criar cadastro</h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label class="form-label">Nome</label><input class="form-control mb-3" name="name" required><label class="form-label">E-mail</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Senha (mínimo 8 caracteres)</label><input class="form-control mb-3" type="password" name="password" minlength="8" required><button class="btn btn-neon w-100">Cadastrar</button></form><p class="mt-3 mb-0">Já possui cadastro? <a href="login.php">Entrar</a></p></div><?php require __DIR__.'/../includes/footer.php';?>
